package pe.ganadoconecta.modulos.sanidad.adaptadores.salida;
import java.sql.Date;import java.time.*;import java.util.*;import org.springframework.dao.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.TransactionSynchronizationManager;
import pe.ganadoconecta.modulos.ganado.aplicacion.AnimalNoEncontradoException;import pe.ganadoconecta.modulos.sanidad.aplicacion.*;import pe.ganadoconecta.modulos.sanidad.dominio.*;
public final class RepositorioAgendaSanitariaPostgres implements RepositorioAgendaSanitaria{
 private final JdbcTemplate jdbc;public RepositorioAgendaSanitariaPostgres(JdbcTemplate j){jdbc=j;}
 @Override public ActividadSanitaria crear(ActividadSanitaria a){transaccion();try{
  if(!existeAnimal(a.ganaderiaId(),a.animalId()))throw new AnimalNoEncontradoException();
  if(a.eventoOrigenId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM sanidad.evento_sanitario WHERE id=? AND ganaderia_id=? AND animal_id=?)",Boolean.class,a.eventoOrigenId(),a.ganaderiaId(),a.animalId())))throw new DatoSanitarioInvalidoException("eventoOrigenId");
  int insertadas=jdbc.update("INSERT INTO sanidad.actividad_agenda(id,ganaderia_id,animal_id,evento_origen_id,tipo,fecha_prevista,descripcion,observaciones,estado,version,creado_por,creado_en) VALUES(?,?,?,?,?,?,?,?,'PENDIENTE',1,?,?) ON CONFLICT (id) DO NOTHING",a.id(),a.ganaderiaId(),a.animalId(),a.eventoOrigenId(),a.tipo().name(),Date.valueOf(a.fechaPrevista()),a.descripcion(),a.observaciones(),a.creadoPor(),OffsetDateTime.ofInstant(a.creadoEn(),ZoneOffset.UTC));return insertadas==1?a:reprocesarCreacion(a);
 }catch(AnimalNoEncontradoException|DatoSanitarioInvalidoException|ConflictoSanitarioException e){throw e;}catch(DuplicateKeyException e){throw new ConflictoSanitarioException();}catch(DataAccessException e){throw new PersistenciaSanitariaException(e);}}
 private ActividadSanitaria reprocesarCreacion(ActividadSanitaria a){List<ActividadSanitaria> filas=jdbc.query("SELECT id,ganaderia_id,animal_id,evento_origen_id,tipo,fecha_prevista,descripcion,observaciones,estado,version,creado_por,creado_en,completado_por,completado_en FROM sanidad.actividad_agenda WHERE ganaderia_id=? AND id=?",(rs,n)->map(rs),a.ganaderiaId(),a.id());if(filas.size()!=1)throw new ConflictoSanitarioException();var x=filas.getFirst();if(!x.animalId().equals(a.animalId())||!Objects.equals(x.eventoOrigenId(),a.eventoOrigenId())||x.tipo()!=a.tipo()||!x.fechaPrevista().equals(a.fechaPrevista())||!x.descripcion().equals(a.descripcion())||!Objects.equals(x.observaciones(),a.observaciones())||!x.creadoPor().equals(a.creadoPor()))throw new ConflictoSanitarioException();return x;}
 @Override public List<ActividadSanitaria> listar(UUID g,UUID animal,TipoActividadSanitaria tipo,EstadoActividadSanitaria estado){try{
  String t=tipo==null?null:tipo.name(),s=estado==null?null:estado.name();return jdbc.query("""
   SELECT id,ganaderia_id,animal_id,evento_origen_id,tipo,fecha_prevista,descripcion,observaciones,estado,version,creado_por,creado_en,completado_por,completado_en
   FROM sanidad.actividad_agenda WHERE ganaderia_id=? AND (CAST(? AS UUID) IS NULL OR animal_id=?) AND (CAST(? AS VARCHAR) IS NULL OR tipo=?) AND (CAST(? AS VARCHAR) IS NULL OR estado=?) ORDER BY fecha_prevista,id
   """,(rs,n)->map(rs),g,animal,animal,t,t,s,s);}catch(DataAccessException e){throw new PersistenciaSanitariaException(e);}}
 @Override public ActividadSanitaria completar(UUID g,UUID id,UUID actor,Instant ahora){transaccion();try{
  List<ActividadSanitaria> filas=jdbc.query("SELECT id,ganaderia_id,animal_id,evento_origen_id,tipo,fecha_prevista,descripcion,observaciones,estado,version,creado_por,creado_en,completado_por,completado_en FROM sanidad.actividad_agenda WHERE ganaderia_id=? AND id=? FOR UPDATE",(rs,n)->map(rs),g,id);
  if(filas.isEmpty())throw new ActividadAgendaNoEncontradaException();var actual=filas.getFirst();if(actual.estado()==EstadoActividadSanitaria.COMPLETADA)return actual;
  jdbc.update("UPDATE sanidad.actividad_agenda SET estado='COMPLETADA',version=2,completado_por=?,completado_en=? WHERE ganaderia_id=? AND id=?",actor,OffsetDateTime.ofInstant(ahora,ZoneOffset.UTC),g,id);
  return new ActividadSanitaria(actual.id(),g,actual.animalId(),actual.eventoOrigenId(),actual.tipo(),actual.fechaPrevista(),actual.descripcion(),actual.observaciones(),EstadoActividadSanitaria.COMPLETADA,2,actual.creadoPor(),actual.creadoEn(),actor,ahora);
 }catch(ActividadAgendaNoEncontradaException e){throw e;}catch(DataAccessException e){throw new PersistenciaSanitariaException(e);}}
 private boolean existeAnimal(UUID g,UUID a){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ganado.animal WHERE ganaderia_id=? AND id=?)",Boolean.class,g,a));}
 private static ActividadSanitaria map(java.sql.ResultSet r)throws java.sql.SQLException{return new ActividadSanitaria(r.getObject("id",UUID.class),r.getObject("ganaderia_id",UUID.class),r.getObject("animal_id",UUID.class),r.getObject("evento_origen_id",UUID.class),TipoActividadSanitaria.valueOf(r.getString("tipo")),r.getDate("fecha_prevista").toLocalDate(),r.getString("descripcion"),r.getString("observaciones"),EstadoActividadSanitaria.valueOf(r.getString("estado")),r.getLong("version"),r.getObject("creado_por",UUID.class),r.getObject("creado_en",OffsetDateTime.class).toInstant(),r.getObject("completado_por",UUID.class),r.getObject("completado_en",OffsetDateTime.class)==null?null:r.getObject("completado_en",OffsetDateTime.class).toInstant());}
 private static void transaccion(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("La agenda sanitaria requiere una transacción");}
}
